//! Picks the recipe that `src/lib.rs` embeds.
//!
//! Default: `recipe/eb_recipe.bin` (committed, generated by
//! `scripts/eb_recipe.py`). `EB_RECIPE=<path>` embeds another one instead,
//! which is how `check.sh` builds a module around a synthetic ROM.
//!
//! A wasm build without a recipe fails here: that module would be useless.
//! A native build without one embeds an empty recipe, so `cargo test` (which
//! feeds the interpreter its own synthetic recipes) and the CLI's `--recipe`
//! work in a tree where the recipe isn't generated yet.

use std::path::PathBuf;

fn main() {
    println!("cargo:rerun-if-env-changed=EB_RECIPE");
    let manifest = PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap());
    let path = match std::env::var_os("EB_RECIPE") {
        // Cargo runs build scripts from the manifest dir, so a relative
        // EB_RECIPE resolves against it.
        Some(p) => manifest.join(p),
        None => manifest.join("recipe").join("eb_recipe.bin"),
    };
    println!("cargo:rerun-if-changed={}", path.display());
    // Also watch the directory, so creating the file reruns this script.
    if let Some(dir) = path.parent() {
        println!("cargo:rerun-if-changed={}", dir.display());
    }

    let embed = if path.is_file() {
        path
    } else {
        let target = std::env::var("TARGET").unwrap_or_default();
        if target.starts_with("wasm32") {
            panic!(
                "\n\nrecipe not found: {}\n\
                 Generate it with `python3 scripts/eb_recipe.py` (needs the ROM), \
                 or set EB_RECIPE=<path> to embed another recipe.\n\n",
                path.display()
            );
        }
        println!(
            "cargo:warning=no recipe at {}; embedding an empty one (native build only)",
            path.display()
        );
        let out = PathBuf::from(std::env::var("OUT_DIR").unwrap()).join("empty_recipe.bin");
        std::fs::write(&out, b"").unwrap();
        out
    };
    println!("cargo:rustc-env=EB_RECIPE_PATH={}", embed.display());
}
